#include <iostream>
#include <vector>
#include <limits>
using namespace std;

int main() {
    int n;
    while (cin >> n, n) {
        vector<int> h(200), r(200); // Using vectors for safety and flexibility
        for (int i = 0; i < n; ++i) {
            cin >> h[i] >> r[i];
        }
        int M; cin >> M;
        for (int i = 0; i < M; ++i) {
            cin >> h[n + i] >> r[n + i];
        }
        n += M;

        vector<vector<int>> m(n, vector<int>(n, numeric_limits<int>::max())); // Initialize to max values
        for (int i = 0; i < n; ++i) {
            m[i][i] = 0; // Distance to self is zero
            for (int j = 0; j < n; ++j) {
                if (h[i] < h[j] && r[i] < r[j]) {
                    m[i][j] = -1; // Set distance for valid pairs
                }
            }
        }

        int ans = numeric_limits<int>::max();
        for (int k = 0; k < n; ++k) {
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    if (m[i][k] != numeric_limits<int>::max() && m[k][j] != numeric_limits<int>::max()) {
                        m[i][j] = min(m[i][j], m[i][k] + m[k][j]);
                    }
                    ans = min(ans, m[i][j]);
                }
            }
        }

        cout << (-ans + 1) << endl;
    }
}

